using System.Collections.Generic;using Microsoft.VisualStudio.TestTools.UnitTesting;using NavisLegacyPlugin.Models.Execution;using NavisLegacyPlugin.Models.Topology;
namespace NavisLegacyPlugin.Topology.Tests{[TestClass]public class TopologyOutcomeIntegrationTests{private static TransferOutcome O(TopologyResolutionStatus s,bool conflict=false){var r=new TopologyResolution(s,"reason",s==TopologyResolutionStatus.Good,90,70,new[]{TestData.Anchor()},TestData.F("owner"),"RID",TestData.Path("A"),new[]{TestData.Candidate(90)});return new TransferOutcome(new TransferSourceIdentity(0,"i","g","f","d"),new TransferPayloadValue[0],new TransferMatchResult(TransferMatchStatus.Matched,"IfcGuid","k","r",null),new TransferOperationResult[0],r,conflict);}[TestMethod]public void Totals_Reconcile(){var set=new TransferOutcomeSet("e","s","x","All","All",TransferExecutionStatus.Completed,new[]{O(TopologyResolutionStatus.Good),O(TopologyResolutionStatus.Vague),O(TopologyResolutionStatus.Ambiguous),O(TopologyResolutionStatus.Unresolved)},"Topology","IfcGuid");Assert.AreEqual(4,set.TopologyApplicable);Assert.AreEqual(1,set.TopologyGood);Assert.AreEqual(1,set.TopologyVague);Assert.AreEqual(1,set.TopologyAmbiguous);Assert.AreEqual(1,set.TopologyUnresolved);}[TestMethod]public void Conflict_IsSeparate(){var set=new TransferOutcomeSet("e","s","x","All","All",TransferExecutionStatus.Completed,new[]{O(TopologyResolutionStatus.Good,true)},"Topology","IfcGuid");Assert.AreEqual(1,set.TopologyGood);Assert.AreEqual(1,set.TopologyConflict);}}}
